print("REVERSE THE LIST USING WHILE LOOP")
numbers=[1,2,3,4,5]
i=4
while i>=0:
    print(numbers[i])
    i=i-1
print("FIND THE SUM USING THE WHILE LOOP")
NUM=[5,10,15,20]
total=0
i=0
while i<=3:
    total=total+NUM[i]
    i=i+1
print(total)